using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ClarityWhirlwindCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Austra/ClarityWhirlwindCustomDescription", order = 0)]
public class ClarityWhirlwindCustomDescription : PurifyCorruptWithMultiplierCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = (battleAction as ClarityWhirlwindAction).SecondPurifyAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)) + "\n" + base.GetActionDescription(amountModified, battleAction);
		if (LanguagesIndexes.IsCurrentLanguageKanji())
		{
			text = text + "\n" + base.localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription).Split('\n')[1];
		}
		return text;
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		string localizedString = base.localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription);
		if (LanguagesIndexes.IsCurrentLanguageKanji())
		{
			return localizedString.Split('\n')[0];
		}
		return localizedString;
	}
}
